import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"TUI guide (terminal user interface)","description":"","frontmatter":{},"headers":[],"relativePath":"manual/tui-guide.md","filePath":"manual/tui-guide.md"}'),i={name:"manual/tui-guide.md"};function o(r,e,l,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="tui-guide-terminal-user-interface" tabindex="-1">TUI guide (terminal user interface) <a class="header-anchor" href="#tui-guide-terminal-user-interface" aria-label="Permalink to &quot;TUI guide (terminal user interface)&quot;">​</a></h1><p>The TUI layer (<code>tui/</code>) is a windowing system on the framebuffer: desktop, taskbar, menus, forms, panels, a text editor and system apps - all keyboard-driven.</p><h2 id="starting-it" tabindex="-1">Starting it <a class="header-anchor" href="#starting-it" aria-label="Permalink to &quot;Starting it&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; tui</span></span></code></pre></div><p>The desktop takes over the screen. (In QEMU, drop <code>-display none</code> and use the SDL/ GTK window so you can see it; the serial console keeps running alongside.)</p><h2 id="the-desktop" tabindex="-1">The desktop <a class="header-anchor" href="#the-desktop" aria-label="Permalink to &quot;The desktop&quot;">​</a></h2><ul><li>A taskbar with a launcher.</li><li>Windows with the standard widget set: menus, forms, text areas, panels.</li><li>The bundled apps cover the system monitor (processes, memory), files, a TUI editor, network status and system info.</li></ul><h2 id="keyboard-model" tabindex="-1">Keyboard model <a class="header-anchor" href="#keyboard-model" aria-label="Permalink to &quot;Keyboard model&quot;">​</a></h2><ul><li>Arrow keys / Tab navigate; Enter activates; Esc backs out.</li><li>The editor uses the same line discipline as the shell line editor.</li><li><code>tui</code> apps are reachable both from the desktop launcher and as individual commands - see the TUI domain in the <a href="./commands/">commands index</a>.</li></ul><h2 id="tui-commands" tabindex="-1">TUI commands <a class="header-anchor" href="#tui-commands" aria-label="Permalink to &quot;TUI commands&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; tui              (enter the desktop)</span></span>
<span class="line"><span>oc&gt; tui-test         (the TUI regression suite)</span></span>
<span class="line"><span>oc&gt; tui-hw           (TUI hardware/render diagnostics)</span></span>
<span class="line"><span>oc&gt; tui-net          (network status app)</span></span>
<span class="line"><span>oc&gt; tui-sysinfo      (system information app)</span></span>
<span class="line"><span>oc&gt; tui-time         (clock/time sources panel)</span></span>
<span class="line"><span>oc&gt; tui-sys          (system monitor)</span></span>
<span class="line"><span>oc&gt; tui-drv          (driver inventory)</span></span>
<span class="line"><span>oc&gt; tui-ext          (extension surface status)</span></span></code></pre></div><h2 id="chinese-console-and-tui" tabindex="-1">Chinese console and TUI <a class="header-anchor" href="#chinese-console-and-tui" aria-label="Permalink to &quot;Chinese console and TUI&quot;">​</a></h2><p>The Chinese layer (<code>chinese</code> command) swaps the console into a 16x16 CJK font with GB encoding and a pinyin IME, and provides CN variants of the hardware/net/sysinfo TUI apps:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; chinese          (status of font/encoding/render/ime)</span></span>
<span class="line"><span>oc&gt; ime -i           (interactive pinyin input line)</span></span>
<span class="line"><span>oc&gt; lang             (language console switch)</span></span></code></pre></div><p>System strings remain ASCII by contract; the Chinese layer renders user content - see <a href="./chinese-console.html">chinese-console</a>.</p><h2 id="extension-surface" tabindex="-1">Extension surface <a class="header-anchor" href="#extension-surface" aria-label="Permalink to &quot;Extension surface&quot;">​</a></h2><p>L1 modules can create TUI windows and widgets through <code>tui/tui_ext.h</code> (37 callable declarations - windows, menus, forms, panels, text). The TUI command bridge itself is the reference implementation: it enumerates the shell command table through the L1 API and renders it as a launcher. Extension guide: <a href="./../l1/tui-ext.html">../l1/tui-ext.md</a>.</p><h2 id="building-without-the-tui" tabindex="-1">Building without the TUI <a class="header-anchor" href="#building-without-the-tui" aria-label="Permalink to &quot;Building without the TUI&quot;">​</a></h2><p><code>make CONFIG_TUI=n</code> drops the TUI (and with <code>CONFIG_CHINESE=n</code> the Chinese layer) from the image - the boot then registers 216 commands (233 - 17). The off-path is real code with ASCII-equivalent routing, not a deleted feature. See <a href="./../dev/build.html">../dev/build.md</a>.</p>`,19)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
